import { chromium } from '@playwright/test';
import { writeFileSync } from 'node:fs';
const dir = 'reference-captures/ordinary-native-d42143e';
const browser = await chromium.connectOverCDP('http://127.0.0.1:9226');
try {
  const page = browser.contexts().flatMap(context => context.pages()).find(page => page.url() === 'http://127.0.0.1:3101/');
  if (!page || !await page.getByRole('dialog', { name: 'Paused', exact: true }).isVisible()) throw new Error('Expected preserved paused ordinary session');
  const canvas = page.locator('.game-canvas canvas');
  const clip = await canvas.boundingBox();
  const rows = [];
  for (const method of ['locator', 'page-clip']) for (let index = 0; index < 3; index++) {
    const start = performance.now();
    if (method === 'locator') await canvas.screenshot({ path: `${dir}/timing-${method}-${index}.png` });
    else await page.screenshot({ clip, path: `${dir}/timing-${method}-${index}.png` });
    rows.push({ method, milliseconds: Math.round(performance.now() - start) });
  }
  writeFileSync(`${dir}/capture-timing.json`, JSON.stringify({ scope: 'Public screenshot latency while gameplay is paused; no gameplay/control/clock changes.', clip, rows }, null, 2) + '\n');
  console.log(JSON.stringify(rows));
} finally { await browser.close(); }

